	title 'Kidding'************************************************************************ Kidding.ASM** Copyright Apple Computer, Inc. 1988* All Rights Reserved** By Steven Glass** This is a file that contains code to go out and see what version* of the OS is running and patch a particular version.** This code is called from inside the QuickDraw Version call.************************************************************************	include 'all.macros'	include '::sys.equs.asm'drvr_dib_ptr	equ $00BD24DibEntry	RECORD 0Ptr	ds.L 1SwitchStatus	ds.W 1UserID	ds.W 1	ENDRDibRecord	RECORD 0link_ptr	ds.L 1entry_ptr	ds.L 1dev_char	ds.w 1blk_cnt	ds.L 1dev_name	ds.b 32slot_num	ds.w 1unit_num	ds.w 1ver_num	ds.w 1dev_id_num	ds.w 1head_dev_link	ds.w 1forward_dev_link	ds.w 1supervisor_req	ds.w 1supervisor_num	ds.w 1dib_device_num	ds.w 1drvr_class	ds.w 1drvr_type	ds.w 1drvr_subtype	ds.w 1cache_mask	ds.w 1block_size	ds.w 1hw_unit_num	ds.w 1	ENDR	title 'YoveGotToBeKidding'*****************************************************************YouveGotToBeKidding	PROC EXPORT** This patches a bug in the generated driver dibs produced* by version 2.0 of GS/OS.** This routine is called by QuickDraw version and by InitTextDev.* It is called by QuickDraw version so that it will be executed* right after the OS is loaded the first time.** This routine is called by InitTextDev because InitTextDev is the* first ROM routine called by the OS after p8 has been run and * control returns to GS/OS.*** When there is something to patch, this code looks at * the dibs and fixes the unit num for * drive 2 The OS sets it incorrectly to one* and it sould be equal to 2.** Before trying to do this however, we look at the OS_Flag.* If the OS flag has bit 0 set, then this code has already been* run.** If the flag is clear, this code has not been run and must* run now.** If it has not been run, I set the bit and then do the* work.** We also set the bit 1 of the OS flag if the OS that is running* is the one we have to patch.  This bit is used later* by code in DeskShutdown to see if it is necessary to * reset bit 0.  Deskshutdown resets bit 0 whenever bit 1 is* set and P8 is active.** Inputs:*	os_flag** Outputs:*	OS_flag** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 21 Nov 88	Steven Glass** This call can be made before the OS is in the system and * the other silly code always installs a valid stack entry * point.  So we cannot relay on the $5C opcode being in the * stackentry point as a test for the existance of the OS.** We check normal entry to see if it is $5c.  If it is not* we exit right away.** ?? ??? ??	Steven Glass** We discovered that the OS did not set the OS Kind byte * from $FF to 1 until just before the application launched.* this made it impossible to rely on the flag for boot time* information.** 25 Jan 89	Steven Glass** But FF, at other times means we are in between p8 and * p16.  So it is not safe to make OS calls.*****************************************************************;-----------------------------------------------------------;; Is there any OS in the system at this time?;	lda >OS_Entry	and #$00FF	cmp #$005C	bne QuickExit;-----------------------------------------------------------;; See if we've been here before.;	lda >OS_Flag		; look at specialbit of os_flag	tax	and #SpecialBit	beq ContinueQuickExit	rtlContinue;-----------------------------------------------------------;; If we've been through this before, and the OS is not; a bad OS, we can quit.;	txa	bit #PatchedOnceBit	beq StillAVirgin	bit #BadOSBit	beq QuickExitStillAVirgin;--------------------------------------------------------------------------------;; Make sure that the right OS is available.;	lda >OS_Boot	; first check to see what os has booted	and #$00FF	cmp #$0001	bne QuickExit	lda >OS_Kind	; second, see what os is active now	and #$00FF	cmp #$0001	beq OSIsP16	cmp #$00FF	; if not 1 or FF, cannot be P16 or GSOS	bne QuickExit	txa	; if FF and the OS has been patched once	and #PatchedOnceBit ; then this is really the intermediate state	bne QuickExit	; and we cannot continue;; If we get to here, then the OS_Kind is FF, and we have not been patched once.; That means that we've encountered the bug in the early OS's that the OS kind; byte was not set until just before the application was run.;OSIsP16	txa	ora #SpecialBit+PatchedOnceBit	sta >OS_Flag		; set it so we won't do it again;-----------------------------------------------------------;; Make the version call using the stack entry  point.;;  Changed on 11/30/88 by Konstantin Othmer; Now the dbr is set to 0 since an old version of the OS (which EA World;  Tour Golf shipped with) assumes the dbr is 0;	phb	;save the dbr	pea #0	;set it to 0	plb	plb	pha	; push space on the stack for the parameter block	tsc	; push a pointer to that word on the stack	inc a	pea 0000	pha	PushWord #$002A	; push the version call number on the stack	jsl OS_StackEntry	; call the OS	pla	; look at the version	plb	;set back to old dbr	and #$7FFF 	; make the proto versions work too.	cmp #$0200	bne QuickExit;-----------------------------------------------------------;; Set the bad os bit so other routines will know later that; they may have something to do.;	lda >OS_Flag	ora #BadOSBit	sta >OS_Flag;-----------------------------------------------------------;; This is the version we must patch!  Make some direct; page space on the stack.;	DefineStackOrigD	wordCount	wordPtr	LONGDibPtr	LONG	pha	; space for the dib ptr	pha	lda >Drvr_Dib_Ptr+2	; the pointer to the dib list	pha	lda >Drvr_Dib_Ptr	pha	pha	; space for the count	phd	; save d-reg	tsc	; turn stack into d-page	tcd	lda [ptr]	; move the count from list to d-page	beq NoDevices	sta Count	lda #4	bra BumpPtrLoop	ldy #DibEntry.UserID	; The user ID must be zero	lda [Ptr],y		; or its a loaded driver	bne NotThisOne	ldy #DibEntry.Ptr+2	lda [Ptr],y	sta DibPtr+2	dey	dey	lda [Ptr],y	sta DibPtr;-----------------------------------------------------------;; Make sure all the conditions in the CheckTable are met.;	ldx #0@CheckLoop	lda >CheckTable,x	tay	lda [DibPtr],y	cmp >CheckTable+2,x	bne NotThisOne	inx	inx	inx	inx	cpx #NumItemsToCheck	bcc @CheckLoop;-----------------------------------------------------------;; Make sure the unit number is not 1	ldy #DIBRecord.unit_num	; this must be other than 1	lda [DibPtr],y	cmp #1	beq NotThisOne;-----------------------------------------------------------;; Yup, this is the one to patch!;	lda #2		; make unit num 2	ldy #DIBRecord.hw_unit_num		sta [DibPtr],y	bra NoDevices		; cannot be more than one to patch		NotThisOne		lda #8BumpPtr	clc	adc ptr	sta ptr	bcc @1	inc ptr+2@1	dec Count	bpl LoopNoDevices	pld	pla	pla	pla	pla	pla;-----------------------------------------------------------;; All done.	rtl;-----------------------------------------------------------;; CheckTable;; Contains an offset in the dibRecord and the value; that must be at that offset.;; For example the dev_char field must be $43EC.;CheckTable	dc.w DIBRecord.dev_char,$43EC	dc.w DIBRecord.slot_num,$0005	dc.w DIBRecord.dev_id_num,3	dc.w DIBRecord.drvr_class,0002	dc.w DIBRecord.drvr_type,0001	dc.w DIBRecord.drvr_subtype,$00C0	dc.w DIBRecord.hw_unit_num,1NumItemsToCheck	equ *-CheckTable	ENDP	END